-- 0001: tenancy, identity, RBAC, audit. Target: TiDB 8.5 (MySQL 8 compatible).
-- Conventions (see docs/database.md):
--  * ids are CHAR(36) UUIDs generated by the application.
--  * tenant-owned tables: tenant_id NOT NULL, UNIQUE (tenant_id, id), composite FKs (tenant_id, x_id) -> x(tenant_id, id)
--    so the database rejects cross-tenant references even though there is no row-level security.
--  * "unique among non-deleted rows" uses a virtual column live = IF(deleted_at IS NULL, 1, NULL) in the unique key.
--  * CHECK constraints are documentation only (tidb_enable_check_constraint is OFF); the API validates.
--  * Statements must be idempotent (DDL is not transactional in TiDB).

CREATE TABLE IF NOT EXISTS tenants (
  id            CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  slug          VARCHAR(63) CHARACTER SET ascii NOT NULL,
  name          VARCHAR(200) NOT NULL,
  status        VARCHAR(16) NOT NULL DEFAULT 'active',
  is_platform   TINYINT(1) NOT NULL DEFAULT 0,
  platform_key  TINYINT AS (IF(is_platform = 1, 1, NULL)) VIRTUAL,
  custom_domain VARCHAR(253) CHARACTER SET ascii NULL,
  timezone      VARCHAR(64) NOT NULL DEFAULT 'UTC',
  country_code  CHAR(2) NULL,
  settings      JSON NULL,
  suspended_at  DATETIME(3) NULL,
  suspended_reason VARCHAR(500) NULL,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at    DATETIME(3) NULL,
  UNIQUE KEY uq_tenants_slug (slug),
  UNIQUE KEY uq_tenants_domain (custom_domain),
  UNIQUE KEY uq_tenants_single_platform (platform_key),
  CONSTRAINT ck_tenants_status CHECK (status IN ('active', 'suspended', 'closed'))
);

CREATE TABLE IF NOT EXISTS tenant_branding (
  tenant_id       CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  product_name    VARCHAR(100) NOT NULL DEFAULT 'Project Dialer',
  logo_url        VARCHAR(1000) NULL,
  favicon_url     VARCHAR(1000) NULL,
  primary_color   CHAR(7) NOT NULL DEFAULT '#2563eb',
  secondary_color CHAR(7) NOT NULL DEFAULT '#0f172a',
  accent_color    CHAR(7) NOT NULL DEFAULT '#16a34a',
  support_email   VARCHAR(254) NULL,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_branding_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

