CREATE TABLE IF NOT EXISTS roles (
  id          CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  tenant_id   CHAR(36) CHARACTER SET ascii NOT NULL,
  `key`       VARCHAR(50) CHARACTER SET ascii NOT NULL,
  name        VARCHAR(100) NOT NULL,
  description VARCHAR(500) NULL,
  is_system   TINYINT(1) NOT NULL DEFAULT 0,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY uq_roles_tenant_id (tenant_id, id),
  UNIQUE KEY uq_roles_tenant_key (tenant_id, `key`),
  CONSTRAINT fk_roles_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS role_permissions (
  tenant_id      CHAR(36) CHARACTER SET ascii NOT NULL,
  role_id        CHAR(36) CHARACTER SET ascii NOT NULL,
  permission_key VARCHAR(64) CHARACTER SET ascii NOT NULL,
  PRIMARY KEY (role_id, permission_key),
  KEY ix_role_permissions_tenant (tenant_id, role_id),
  CONSTRAINT fk_rp_role FOREIGN KEY (tenant_id, role_id) REFERENCES roles (tenant_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rp_permission FOREIGN KEY (permission_key) REFERENCES permissions (`key`) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS teams (
  id          CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  tenant_id   CHAR(36) CHARACTER SET ascii NOT NULL,
  name        VARCHAR(100) COLLATE utf8mb4_general_ci NOT NULL,
  department  VARCHAR(100) NULL,
  leader_user_id CHAR(36) CHARACTER SET ascii NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at  DATETIME(3) NULL,
  live        TINYINT AS (IF(deleted_at IS NULL, 1, NULL)) VIRTUAL,
  UNIQUE KEY uq_teams_tenant_id (tenant_id, id),
  UNIQUE KEY uq_teams_tenant_name (tenant_id, name, live),
  CONSTRAINT fk_teams_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS users (
  id                  CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  tenant_id           CHAR(36) CHARACTER SET ascii NOT NULL,
  email               VARCHAR(254) COLLATE utf8mb4_general_ci NOT NULL,
  display_name        VARCHAR(200) NOT NULL,
  password_hash       VARCHAR(255) CHARACTER SET ascii NOT NULL,
  status              VARCHAR(16) NOT NULL DEFAULT 'active',
  team_id             CHAR(36) CHARACTER SET ascii NULL,
  failed_login_count  INT NOT NULL DEFAULT 0,
  locked_until        DATETIME(3) NULL,
  last_login_at       DATETIME(3) NULL,
  created_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at          DATETIME(3) NULL,
  live                TINYINT AS (IF(deleted_at IS NULL, 1, NULL)) VIRTUAL,
  UNIQUE KEY uq_users_tenant_id (tenant_id, id),
  UNIQUE KEY uq_users_tenant_email (tenant_id, email, live),
  KEY ix_users_tenant_team (tenant_id, team_id),
  CONSTRAINT fk_users_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_users_team FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id),
  CONSTRAINT ck_users_status CHECK (status IN ('active', 'disabled', 'invited'))
);

-- Platform super admins. Writable ONLY by the dialer_platform DB user; the API user can only SELECT,
-- so no tenant-facing code path can ever grant platform privileges.
CREATE TABLE IF NOT EXISTS platform_admins (
  user_id     CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  tenant_id   CHAR(36) CHARACTER SET ascii NOT NULL,
  granted_by  CHAR(36) CHARACTER SET ascii NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_platform_admins_user FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS user_roles (
  tenant_id  CHAR(36) CHARACTER SET ascii NOT NULL,
  user_id    CHAR(36) CHARACTER SET ascii NOT NULL,
  role_id    CHAR(36) CHARACTER SET ascii NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id, role_id),
  KEY ix_user_roles_role (tenant_id, role_id),
  CONSTRAINT fk_ur_user FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_ur_role FOREIGN KEY (tenant_id, role_id) REFERENCES roles (tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS refresh_tokens (
  id          CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  tenant_id   CHAR(36) CHARACTER SET ascii NOT NULL,
  user_id     CHAR(36) CHARACTER SET ascii NOT NULL,
  family_id   CHAR(36) CHARACTER SET ascii NOT NULL,
  token_hash  CHAR(64) CHARACTER SET ascii NOT NULL,
  expires_at  DATETIME(3) NOT NULL,
  rotated_at  DATETIME(3) NULL,
  revoked_at  DATETIME(3) NULL,
  user_agent  VARCHAR(500) NULL,
  ip_address  VARCHAR(45) CHARACTER SET ascii NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY ix_refresh_family (tenant_id, family_id),
  KEY ix_refresh_user (tenant_id, user_id),
  CONSTRAINT fk_refresh_user FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id) ON DELETE CASCADE
);

-- Append-only for both DB users (INSERT + SELECT grants only).
CREATE TABLE IF NOT EXISTS audit_logs (
  id              CHAR(36) CHARACTER SET ascii NOT NULL PRIMARY KEY,
  tenant_id       CHAR(36) CHARACTER SET ascii NOT NULL,
  actor_user_id   CHAR(36) CHARACTER SET ascii NULL,
  actor_tenant_id CHAR(36) CHARACTER SET ascii NULL,
  action          VARCHAR(100) NOT NULL,
  entity_type     VARCHAR(50) NULL,
  entity_id       CHAR(36) CHARACTER SET ascii NULL,
  metadata        JSON NULL,
  ip_address      VARCHAR(45) CHARACTER SET ascii NULL,
  correlation_id  VARCHAR(100) NULL,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY ix_audit_tenant_time (tenant_id, created_at),
  KEY ix_audit_entity (tenant_id, entity_type, entity_id),
  CONSTRAINT fk_audit_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);
